import BaseComponent from 'c/baseComponent';

let CURRENT_DRAG_DATA = null;

export default class DraggableComponent extends BaseComponent {
    // Internal state
    _dragEnterCounter = 0; // Critical: tracks depth of child elements entered

    isDragging = false;
    isDropTarget = false;

    // Expose the static data to child components (like WorkItemCard)
    get currentDragData() {
        return CURRENT_DRAG_DATA;
    }

    set currentDragData(value) {
        CURRENT_DRAG_DATA = value;
    }

    get dragData() {
        throw new Error('dragData getter must be implemented by subclass');
    }

    canDrop(sourceData) {
        throw new Error('canDrop method must be implemented by subclass');
    }

    onDropSuccess(sourceData) {
        throw new Error('onDropSuccess method must be implemented by subclass');
    }

    get dragClasses() {
        const classes = ['drag-row']; // Ensure this class exists in your CSS or matches child CSS
        if (this.isDragging) {
            classes.push('dragging');
        }
        if (this.isDropTarget) {
            classes.push('drop-target');
        }
        return classes.join(' ');
    }

    handleDragStart(event) {
        this.isDragging = true;
        this._dragEnterCounter = 0; // Reset

        // Firefox requirement
        event.dataTransfer.effectAllowed = 'move';

        const data = this.dragData;
        this.currentDragData = this.dragData;

        event.dataTransfer.setData('text/plain', JSON.stringify(data));

        this.dispatchEvent(
            new CustomEvent('dragstart', {
                detail: data,
                bubbles: true,
                composed: true
            })
        );
    }

    handleDragEnd(event) {
        this.resetDragState();

        this.dispatchEvent(
            new CustomEvent('dragend', {
                bubbles: true,
                composed: true
            })
        );
    }

    handleDragEnter(event) {
        event.preventDefault();
        event.stopPropagation();

        const sourceData = this.currentDragData;

        if (sourceData && this.canDrop(sourceData)) {
            this._dragEnterCounter++;
            if (this._dragEnterCounter === 1) {
                this.isDropTarget = true;
            }
        }
    }

    handleDragOver(event) {
        const sourceData = this.currentDragData;
        if (!sourceData) return;

        // USE HOOK: Ask child validation logic
        if (this.canDrop(sourceData)) {
            event.preventDefault(); // Allow drop
            event.dataTransfer.dropEffect = 'move';

            // Redundant visual safety
            if (!this.isDropTarget) {
                this.isDropTarget = true;
            }
        } else {
            this.isDropTarget = false;
        }
    }

    handleDragLeave(event) {
        event.stopPropagation();

        // Decrement counter
        this._dragEnterCounter--;

        if (this._dragEnterCounter <= 0) {
            this.isDropTarget = false;
            this._dragEnterCounter = 0; // Safety clamp

